//! The core as a native static library with a plain C ABI (include/fold_core.h, generated by cbindgen), for a host that links it
//! in-process (Allie's native tree). The same JSON texts as the WebAssembly module (src/wasm.rs), but a buffer comes back as a
//! `{ptr, len}` struct rather than packed in a u64 (pointers here are 64 bits), and every symbol carries the `fold_core_` prefix.
//!
//!   fold_core_alloc(len) -> ptr                 the host writes its UTF-8 input there
//!   fold_core_fold_json(ptr, len) -> buf        `{root, files, opts}` → `[[id, node], ...]`
//!   fold_core_walk_json(ptr, len) -> buf        `{nodes, opts, facto?}` → `{walk, verdict, facto?}`
//!   fold_core_ax_json(ptr, len) -> buf          `{node, path, mode, href, localTimeZone?}` → one fold's accessibility tree
//!   fold_core_rotor_json(ptr, len) -> buf       the rotor and yank (src/rotor.rs), `{op, tree, state?, at?, key?, opts?}`
//!   fold_core_free(buf.ptr, buf.len)            frees a returned buffer
//!
//! A call takes its input buffer and frees it; the host frees only what comes back. A failure is `{"error": "..."}`, never a crash.
//! Built without `tzdb` (packages.native), the library imports `fold_core_tz_offset` from the host (src/tz.rs).

use crate::wasm::{ax_text, fold_text, rotor_text, walk_text};

/// A buffer the library owns: JSON text, `len` bytes at `ptr`. Free it with `fold_core_free(ptr, len)`.
#[repr(C)]
pub struct FoldCoreBuf {
    pub ptr: *mut u8,
    pub len: usize,
}

/// A buffer of `len` bytes for the host to write its input into, given to one call (which frees it).
#[no_mangle]
pub extern "C" fn fold_core_alloc(len: usize) -> *mut u8 {
    let mut b = Vec::<u8>::with_capacity(len.max(1));
    let p = b.as_mut_ptr();
    std::mem::forget(b);
    p
}

/// # Safety
/// `ptr` and `len` are a buffer a call returned, freed once.
#[no_mangle]
pub unsafe extern "C" fn fold_core_free(ptr: *mut u8, len: usize) {
    drop(Vec::from_raw_parts(ptr, 0, len.max(1)));
}

unsafe fn call(ptr: *mut u8, len: usize, f: fn(&str) -> String) -> FoldCoreBuf {
    let out = f(std::str::from_utf8(std::slice::from_raw_parts(ptr, len)).unwrap_or(""));
    fold_core_free(ptr, len);
    // never empty (JSON text), so its allocation is exactly `len` bytes, as fold_core_free frees it
    let out = out.into_bytes().into_boxed_slice();
    FoldCoreBuf { len: out.len(), ptr: Box::into_raw(out) as *mut u8 }
}

/// # Safety
/// `ptr` and `len` are UTF-8 the host wrote into a buffer from `fold_core_alloc(len)`; the call frees it.
#[no_mangle]
pub unsafe extern "C" fn fold_core_fold_json(ptr: *mut u8, len: usize) -> FoldCoreBuf {
    call(ptr, len, fold_text)
}

/// # Safety
/// `ptr` and `len` are UTF-8 the host wrote into a buffer from `fold_core_alloc(len)`; the call frees it.
#[no_mangle]
pub unsafe extern "C" fn fold_core_walk_json(ptr: *mut u8, len: usize) -> FoldCoreBuf {
    call(ptr, len, walk_text)
}

/// # Safety
/// `ptr` and `len` are UTF-8 the host wrote into a buffer from `fold_core_alloc(len)`; the call frees it.
#[no_mangle]
pub unsafe extern "C" fn fold_core_ax_json(ptr: *mut u8, len: usize) -> FoldCoreBuf {
    call(ptr, len, ax_text)
}

/// # Safety
/// `ptr` and `len` are UTF-8 the host wrote into a buffer from `fold_core_alloc(len)`; the call frees it.
#[no_mangle]
pub unsafe extern "C" fn fold_core_rotor_json(ptr: *mut u8, len: usize) -> FoldCoreBuf {
    call(ptr, len, rotor_text)
}
